/*
  Password Recovery System
  Single-file Bun HTTPS server and vanilla HTML client.
  Requirement mappings are noted in concise comments throughout.
*/

type Stage =
  | "start"
  | "requested"
  | "verified"
  | "mfa"
  | "passwordChanged"
  | "authenticated"
  | "privacyAccepted";

type Attempt = { count: number; blockedUntil: number; lastFailure: number };

type Account = {
  id: string;
  identifier: string;
  passwordHash: string;
};

type Session = {
  id: string;
  csrf: string;
  createdAt: number;
  expiresAt: number;
  stage: Stage;
  accountId?: string;
  throttleIdentifier?: string;
  resetToken?: string;
  resetExpires?: number;
  resetUsed?: boolean;
  manualCode?: string;
  mfaCode?: string;
  authenticated: boolean;
  privacyAccepted: boolean;
};

const sessions = new Map<string, Session>();
const failedAttempts = new Map<string, Attempt>();

/*
  OWASP Authentication: password hashes are scoped to internal account records.
  Account identifiers are never returned by the portal or API.
*/
const initialPasswordHash = await Bun.password.hash("HospitalDemo!2026", { algorithm: "bcrypt" });
const accounts = new Map<string, Account>([
  [
    "account-helen",
    {
      id: "account-helen",
      identifier: "helena@example.com",
      passwordHash: initialPasswordHash,
    },
  ],
  [
    "recovery-sink",
    {
      id: "recovery-sink",
      identifier: "",
      passwordHash: initialPasswordHash,
    },
  ],
]);

const RECOVERY_SINK_ACCOUNT_ID = "recovery-sink";
const RESET_LIFETIME_MS = 10 * 60 * 1000;
const SESSION_LIFETIME_MS = 30 * 60 * 1000;
const ATTEMPT_RETENTION_MS = 15 * 60 * 1000;
const TEST_RECOVERY_CODE = "RECOVERY-DEMO-482913";
const TEST_MFA_CODE = "246810";

function randomValue(bytes = 32): string {
  const value = new Uint8Array(bytes);
  crypto.getRandomValues(value);
  return Buffer.from(value).toString("base64url");
}

/* Security Misconfiguration: every server-side session has authoritative timestamps. */
function createSession(): Session {
  const now = Date.now();
  return {
    id: randomValue(32),
    csrf: randomValue(32),
    createdAt: now,
    expiresAt: now + SESSION_LIFETIME_MS,
    stage: "start",
    authenticated: false,
    privacyAccepted: false,
  };
}

function cleanupExpiredSessions(): void {
  const now = Date.now();
  for (const [id, session] of sessions) {
    if (session.expiresAt <= now) sessions.delete(id);
  }
  for (const [key, attempt] of failedAttempts) {
    if (attempt.blockedUntil <= now && attempt.lastFailure + ATTEMPT_RETENTION_MS <= now) {
      failedAttempts.delete(key);
    }
  }
}

function cookieSessionId(request: Request): string | undefined {
  const cookie = request.headers.get("cookie") || "";
  const match = cookie.match(/(?:^|;\s*)recovery_session=([A-Za-z0-9_-]{20,})/);
  return match?.[1];
}

/* Expired IDs are rejected and deleted even where a browser retained its cookie. */
function getSession(request: Request): { session: Session; isNew: boolean } {
  const id = cookieSessionId(request);
  if (id) {
    const existing = sessions.get(id);
    if (existing) {
      if (existing.expiresAt > Date.now()) return { session: existing, isNew: false };
      sessions.delete(id);
    }
  }
  const session = createSession();
  sessions.set(session.id, session);
  return { session, isNew: true };
}

function securityHeaders(nonce: string): Headers {
  return new Headers({
    "Strict-Transport-Security": "max-age=31536000; includeSubDomains",
    "Content-Security-Policy":
      `default-src 'self'; script-src 'nonce-${nonce}'; style-src 'nonce-${nonce}'; ` +
      "img-src 'self' data:; connect-src 'self'; font-src 'none'; object-src 'none'; " +
      "base-uri 'none'; frame-ancestors 'none'; form-action 'self'",
    "X-Frame-Options": "DENY",
    "X-Content-Type-Options": "nosniff",
    "Referrer-Policy": "no-referrer",
    "Permissions-Policy": "camera=(), microphone=(), geolocation=(), payment=()",
    "Cache-Control": "no-store, max-age=0, private",
    Pragma: "no-cache",
  });
}

function attachSessionCookie(headers: Headers, session: Session, isNew: boolean): void {
  if (isNew) {
    const remainingSeconds = Math.max(1, Math.floor((session.expiresAt - Date.now()) / 1000));
    headers.append(
      "Set-Cookie",
      `recovery_session=${session.id}; Path=/; Secure; HttpOnly; SameSite=Strict; Max-Age=${remainingSeconds}`,
    );
  }
}

function json(
  body: Record<string, unknown>,
  session: Session,
  isNew: boolean,
  status = 200,
): Response {
  const headers = securityHeaders(randomValue(16));
  headers.set("Content-Type", "application/json; charset=utf-8");
  attachSessionCookie(headers, session, isNew);
  return new Response(JSON.stringify(body), { status, headers });
}

function textResponse(text: string, status = 400): Response {
  const headers = securityHeaders(randomValue(16));
  headers.set("Content-Type", "text/plain; charset=utf-8");
  return new Response(text, { status, headers });
}

function validIdentifier(value: unknown): value is string {
  return typeof value === "string" && /^[A-Za-z0-9@._+\- ]{3,120}$/.test(value);
}

function normalizedIdentifier(value: unknown): string | undefined {
  if (!validIdentifier(value)) return undefined;
  return value.trim().toLowerCase();
}

function validCode(value: unknown): value is string {
  return typeof value === "string" && /^[A-Za-z0-9-]{4,100}$/.test(value);
}

function validPassword(value: unknown): value is string {
  return typeof value === "string" && value.length >= 12 && value.length <= 128;
}

function strongPassword(password: string): boolean {
  return (
    password.length >= 12 &&
    /[a-z]/.test(password) &&
    /[A-Z]/.test(password) &&
    /[0-9]/.test(password) &&
    /[^A-Za-z0-9]/.test(password)
  );
}

/*
  OWASP Authentication: shared server-side throttling is keyed by a safely
  normalized identifier and observed source IP, not by a disposable session.
*/
function sourceIp(request: Request, server: any): string {
  try {
    const address = server?.requestIP?.(request)?.address;
    return typeof address === "string" && /^[0-9a-fA-F:.]{1,64}$/.test(address)
      ? address
      : "unknown";
  } catch {
    return "unknown";
  }
}

function throttleIdentifier(session: Session, supplied?: unknown): string {
  const normalized = normalizedIdentifier(supplied);
  if (normalized) return normalized;
  if (session.throttleIdentifier) return session.throttleIdentifier;
  if (session.accountId) return `account-${session.accountId}`;
  return "unknown";
}

function attemptKey(action: string, identifier: string, ip: string): string {
  return `${action}\u0000${identifier}\u0000${ip}`;
}

function allowed(action: string, identifier: string, ip: string): boolean {
  const attempt = failedAttempts.get(attemptKey(action, identifier, ip));
  return !attempt || attempt.blockedUntil <= Date.now();
}

function recordFailure(action: string, identifier: string, ip: string): void {
  const now = Date.now();
  const key = attemptKey(action, identifier, ip);
  const current = failedAttempts.get(key) || { count: 0, blockedUntil: 0, lastFailure: now };
  current.count += 1;
  current.lastFailure = now;

  /* Escalating temporary delays persist across fresh browser sessions. */
  const delays = [0, 1_000, 5_000, 30_000, 60_000, 5 * 60_000];
  current.blockedUntil = now + delays[Math.min(current.count - 1, delays.length - 1)];
  failedAttempts.set(key, current);
}

function clearAttempts(action: string, identifier: string, ip: string): void {
  failedAttempts.delete(attemptKey(action, identifier, ip));
}

function stageData(session: Session): Record<string, unknown> {
  return {
    stage: session.stage,
    csrf: session.csrf,
    authenticated: session.authenticated,
    privacyAccepted: session.privacyAccepted,
  };
}

/* Internal lookup only: account records and identifiers never leave the server. */
function findAccountByIdentifier(identifier: string): Account | undefined {
  const normalized = identifier.trim().toLowerCase();
  for (const account of accounts.values()) {
    if (account.identifier && timingSafeEqual(normalized, account.identifier)) return account;
  }
  return undefined;
}

async function requestBody(request: Request): Promise<Record<string, unknown> | null> {
  const length = Number(request.headers.get("content-length") || "0");
  if (length > 4096) return null;
  try {
    const value = await request.json();
    return value && typeof value === "object" && !Array.isArray(value)
      ? value as Record<string, unknown>
      : null;
  } catch {
    return null;
  }
}

function csrfValid(request: Request, session: Session, body: Record<string, unknown> | null): boolean {
  const token = request.headers.get("x-csrf-token") || body?.csrf;
  return typeof token === "string" && token.length === session.csrf.length &&
    timingSafeEqual(token, session.csrf);
}

function timingSafeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let difference = 0;
  for (let i = 0; i < a.length; i++) difference |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return difference === 0;
}

